<script setup>
import { computed, onMounted, ref } from 'vue'
import { ArrowUpRight, CheckCircle2, Database, CloudSun } from '@lucide/vue'
import Chart from '../components/Chart.vue'
import { api, fmt, cityNames, baseChart } from '../lib/api'
const props = defineProps({ meta: Object, year: String })
const data = ref(null), error = ref('')
const stationData = ref(null)
onMounted(async () => { try { data.value = await api('quality') } catch (e) { error.value = e.message } })
onMounted(async () => { stationData.value = await api('stations/meta').catch(() => null) })
const rows = computed(() => (data.value?.rows || []).filter(r => props.year === 'all' || r.year === Number(props.year)))
const option = computed(() => ({ ...baseChart, grid: { top: 5, left: 60, right: 20, bottom: 32 }, xAxis: { type: 'category', data: props.meta.years, axisLine: { show: false }, axisTick: { show: false }, axisLabel: { fontSize: 10 } }, yAxis: { type: 'category', data: Object.values(cityNames), axisLine: { show: false }, axisTick: { show: false } }, visualMap: { show: false, min: 85, max: 100, inRange: { color: ['#eee5d1', '#c4d3ad', '#3b8467'] } }, tooltip: { formatter: p => `${Object.values(cityNames)[p.value[1]]} · ${props.meta.years[p.value[0]]}<br/>有效观测覆盖率 ${fmt(p.value[2], 2)}%` }, series: [{ type: 'heatmap', data: (data.value?.rows || []).map(r => [props.meta.years.indexOf(r.year), Object.keys(cityNames).indexOf(r.city_id), (1 - r.pm25_missing_ratio) * 100]), label: { show: true, formatter: p => fmt(p.value[2], 1), color: '#fff', fontSize: 10 }, itemStyle: { borderColor: '#fff', borderWidth: 3, borderRadius: 3 } }] }))
</script>
<template>
  <div v-if="error" class="error-box">{{ error }}</div><div v-if="!data" class="page-loader"><span class="spinner"></span> 正在读取数据质量报告…</div>
  <template v-else>
    <section v-if="stationData?.summary.status==='complete'" class="panel"><div class="panel-heading"><h2>新增站点数据 · 2022—2025</h2><a href="#stations" class="button text small">查看站点与 GPU <ArrowUpRight :size="13" /></a></div><p class="station-copy">{{ fmt(stationData.summary.stations,0) }} 个历史站点 · {{ fmt(stationData.summary.valid_pm25,0) }} 条有效 PM₂.₅ 站点小时 · {{ fmt(stationData.summary.grid_hours,0) }} 行完整小时网格。</p><p class="station-copy">新增全国逐站小时原始归档 {{ fmt(stationData.summary.raw_archive_bytes/1e9,2) }} GB，共 {{ fmt(stationData.summary.source_file_count,0) }} 份文件；源数据覆盖 {{ stationData.summary.source_days }} / {{ stationData.summary.expected_days }} 天。气象为同城共享的 ERA5 格点资料。</p><div class="panel-note">下方为原 2015—2025 城市版的质量报告；两类数据保留各自统计口径。</div></section>
    <section class="kpi-grid"><article class="kpi-card featured"><div class="kpi-label">六城小时网格</div><div class="kpi-number">578,592</div><div class="kpi-bottom">完整展开，缺测保留为空</div></article><article class="kpi-card"><div class="kpi-label">有效 PM₂.₅ 观测</div><div class="kpi-number">564,028</div><div class="kpi-bottom">{{ fmt(data.summary.pm25_valid_hours_all_cities / data.summary.panel_rows * 100, 2) }}% 有效覆盖率</div></article><article class="kpi-card"><div class="kpi-label">原始数据总量</div><div class="kpi-number">1.70<small>GB</small></div><div class="kpi-bottom">4,011 份空气质量 + 66 份气象</div></article><article class="kpi-card"><div class="kpi-label">整日源文件缺失</div><div class="kpi-number">07<small>天</small></div><div class="kpi-bottom">已向原站复查并记录</div></article></section>
    <section class="panel"><div class="panel-heading"><div><div class="section-kicker">OBSERVATION COVERAGE</div><h2>十一年观测的完整程度</h2></div><span class="unit-label">有效 PM₂.₅ 小时占比 · %</span></div><Chart :option="option" height="250px" label="六个城市十一年PM2.5有效观测覆盖率" /><div class="panel-note">缺失包括整日文件缺失、部分小时缺失及城市观测单元格为空。</div></section>
    <div class="two-column-grid"><section class="panel source-card"><Database :size="22" /><h2>空气质量观测</h2><p>中国环境监测总站发布的城市平均数据，由 quotsoft 存档。公开归档与原站跨年份交叉核验，逐文件保留来源及 SHA-256。</p><a href="https://quotsoft.net/air/" target="_blank" rel="noreferrer">查看数据源 <ArrowUpRight :size="13" /></a></section><section class="panel source-card"><CloudSun :size="22" /><h2>气象再分析资料</h2><p>Open-Meteo 提供的 ERA5 小时数据，在各城市代表坐标提取。气温、湿度、气压、风速、风向与降水六个变量无空值。</p><a href="https://open-meteo.com/en/docs/historical-weather-api" target="_blank" rel="noreferrer">查看气象说明 <ArrowUpRight :size="13" /></a></section></div>
    <section class="panel"><div class="panel-heading"><div><div class="section-kicker">QUALITY REPORT</div><h2>逐年逐城覆盖报告</h2></div><span class="subtle-tag">{{ rows.length }} 条记录</span></div><div class="table-scroll quality-table"><table><thead><tr><th>年份</th><th>城市</th><th class="numeric">预期小时</th><th class="numeric">有效观测</th><th class="numeric">PM₂.₅ 年均</th><th class="numeric">缺失比例</th></tr></thead><tbody><tr v-for="row in rows" :key="`${row.year}-${row.city_id}`"><td>{{ row.year }}</td><td>{{ row.city_name }}</td><td class="numeric">{{ fmt(row.expected_hours, 0) }}</td><td class="numeric">{{ fmt(row.pm25_valid_hours, 0) }}</td><td class="numeric strong-value">{{ fmt(row.pm25_mean) }}</td><td class="numeric">{{ fmt(row.pm25_missing_ratio * 100, 2) }}%</td></tr></tbody></table></div></section>
    <section class="panel missing-panel"><h3>缺失源文件日期</h3><div class="date-tags"><span v-for="day in data.summary.source_missing_dates" :key="day">{{ day.slice(0,4) }}-{{ day.slice(4,6) }}-{{ day.slice(6,8) }}</span></div><div class="verification-line"><CheckCircle2 :size="15" />4 项数据处理测试通过 <span>·</span>48 项原始值与未来标签抽查通过 <span>·</span>Parquet 导出后重新读取核验通过</div></section>
  </template>
</template>
